}

/* Card styling */
.card {
  width: 320px;
  padding: 24px;
  background-color: white;
  border-radius: 12px;
  box-shadow: 0 10px 30px rgb(0 0 0 / 0.12);
}

/* Layout container */
.container {
  width: min(100% - 2rem, 1200px);
  margin-inline: auto;
}

/* Keep this fallback for older embedded browsers. */
.card {
  margin-left: auto;
  margin-right: auto;
}

* {
  box-sizing: border-box;
}

p {
  color: #334155;
}

.card {
  padding: 1rem;
}

#main-header {
  min-height: 64px;
}

input[type="email"] {
  border-color: steelblue;
}

button[disabled] {
  opacity: 0.5;
}

[data-theme="dark"] {
  color-scheme: dark;
}

[href^="https://"] {
  text-decoration: underline;
}

.card p {
  margin-block: 0.5rem;
}

.card > header {
  padding: 1rem;
}

h2 + p {
  margin-top: 0;
}

h2 ~ p {
  color: #64748b;
}

button:hover {
  transform: translateY(-1px);
}

button:focus-visible {
  outline: 3px solid currentColor;
  outline-offset: 3px;
}

li:nth-child(2n) {
  background: #f8fafc;
}

input:not(:placeholder-shown) {
  border-color: green;
}

.badge::before {
  content: "";
  display: inline-block;
  width: 0.5rem;
  height: 0.5rem;
  margin-inline-end: 0.5rem;
  border-radius: 50%;
  background: currentColor;
}

p {
  color: black;
}

.card p {
  color: blue;
}

#article .card p {
  color: red;
}

@layer reset, base, components, utilities;

@layer base {
  body {
    font-family: system-ui, sans-serif;
  }
}

@layer utilities {
  .hidden {
    display: none;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

.card {
  width: 300px;
  padding: 20px;
  border: 4px solid #334155;
}

.container {
  width: min(100% - 2rem, 1200px);
  min-height: 100dvh;
}

.card {
  width: min(100%, 420px);
  min-height: 200px;
}

.panel {
  padding-block: 1.5rem;
  padding-inline: 2rem;
  margin-inline: auto;
  border-inline-start: 4px solid currentColor;
}

.code-panel {
  max-height: 400px;
  overflow: auto;
  overscroll-behavior: contain;
}

:root {
  --color-primary: #2563eb;
  --color-text: rgb(15 23 42);
  --color-muted: hsl(215 16% 47%);
  --color-overlay: rgb(0 0 0 / 0.5);
}

.hero {
  background:
    linear-gradient(rgb(15 23 42 / 0.72), rgb(15 23 42 / 0.72)),
    url("hero.jpg") center / cover no-repeat;
}

body {
  font-family:
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
}

.article {
  font-size: 1rem;
  line-height: 1.7;
  letter-spacing: 0.01em;
  max-inline-size: 70ch;
}

.article h1 {
  font-size: clamp(2rem, 5vw, 4rem);
  line-height: 1.05;
}

.article {
  max-width: 70ch;
}

.article p {
  margin-block: 1rem;
}

.toolbar {
  display: flex;
}

.badge {
  display: inline-block;
}

.desktop-only {
  display: none;
}

.card {
  position: relative;
}

.card__badge {
  position: absolute;
  inset-block-start: 1rem;
  inset-inline-end: 1rem;
}

.modal {
  position: fixed;
  inset: 0;
  z-index: 1000;
}

.modal__dialog {
  position: relative;
  z-index: 1;
}

.toolbar {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.center {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 300px;
}

.sidebar {
  flex: 0 0 240px;
}

.content {
  flex: 1 1 auto;
  min-width: 0;
}

.cards {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.card {
  flex: 1 1 280px;
}

.nav {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.nav__actions {
  margin-inline-start: auto;
}

.layout {
  display: grid;
  grid-template-columns: 240px 1fr;
  gap: 2rem;
}

.products {
  display: grid;
  grid-template-columns: repeat(
    auto-fit,
    minmax(250px, 1fr)
  );
  gap: 1.5rem;
}

.app {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-areas:
    "sidebar header"
    "sidebar main";
}

.header { grid-area: header; }
.sidebar { grid-area: sidebar; }
.main { grid-area: main; }

.grid {
  display: grid;
  place-items: center;
  min-height: 400px;
}

.feed {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: minmax(150px, auto);
  gap: 1rem;
}

.container {
  width: min(100% - 2rem, 1200px);
  margin-inline: auto;
}

.navigation {
  display: flex;
}

@media (max-width: 700px) {
  .navigation {
    flex-direction: column;
  }
}

.dashboard {
  display: grid;
  grid-template-columns: 1fr;
}

@media (min-width: 800px) {
  .dashboard {
    grid-template-columns: 240px 1fr;
  }
}

.card-list {
  container-type: inline-size;
}

.card {
  display: grid;
  gap: 1rem;
}

@container (min-width: 500px) {
  .card {
    grid-template-columns: 160px 1fr;
  }
}

.avatar {
  width: 64px;
  aspect-ratio: 1;
  object-fit: cover;
  object-position: center;
  border-radius: 50%;
}

.content {
  width: calc(100% - 2rem);
  margin-inline: auto;
}

.sidebar {
  width: calc(100vw - 320px);
}

h1 {
  font-size: clamp(2rem, 5vw, 4rem);
}

.container {
  width: min(100% - 2rem, 1200px);
}

.panel {
  padding: max(1rem, 3vw);
}

.hero {
  min-height: 100dvh;
  padding-block: 5svh;
}

.video {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
}

.button {
  background: #2563eb;
  transition:
    background-color 180ms ease,
    transform 180ms ease;
}

.button:hover {
  background: #1d4ed8;
  transform: translateY(-2px);
}

.card:hover {
  transform: translateY(-6px) scale(1.01);
}

.icon {
  transform: rotate(45deg);
}

.panel {
  transition: transform 300ms cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes fade-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.card {
  animation: fade-in 400ms ease-out both;
}

.loader {
  animation:
    spin 1s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

:root {
  --space-md: 1rem;
  --radius-md: 0.75rem;
  --color-primary: #2563eb;
}

.button {
  padding: var(--space-md);
  border-radius: var(--radius-md);
  background: var(--color-primary);
}

.button {
  color: var(--button-text, white);
  background: var(--button-background, #2563eb);
}

:root {
  --surface: white;
  --text: #0f172a;
}

@media (prefers-color-scheme: dark) {
  :root {
    --surface: #0f172a;
    --text: #f8fafc;
  }
}

body {
  background: var(--surface);
  color: var(--text);
}

.layout {
  display: grid;
  grid-template-columns: max-content 1fr;
}

.sidebar {
  width: fit-content;
  max-width: 20rem;
}

.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}

.card {
  display: grid;
  grid-template-rows: subgrid;
  grid-row: span 3;
}

.sidebar {
  position: sticky;
  inset-block-start: 1rem;
  align-self: start;
}

.card {
  margin-inline: auto;
  padding-block: 1.5rem;
  padding-inline: 1rem;
  border-block-end: 1px solid #cbd5e1;
}

.field {
  display: grid;
  gap: 0.5rem;
}

input,
textarea,
select {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid #94a3b8;
  border-radius: 0.5rem;
  font: inherit;
}

input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 2px;
}

a:focus-visible,
button:focus-visible {
  outline: 3px solid currentColor;
  outline-offset: 4px;
}

.field--error input {
  border-color: #b91c1c;
}

.field--error .message {
  color: #991b1b;
  font-weight: 600;
}

.card {
  display: grid;
  gap: 1rem;
  padding: 1.5rem;
  border: 1px solid var(--border-color);
}

.card__title {
  margin: 0;
}

.card__actions {
  display: flex;
  gap: 0.75rem;
}

.card {}
.card__title {}
.card__actions {}
.card--featured {}
.card--compact {}

@layer reset, base, components, utilities;

@layer reset {
  *, *::before, *::after {
    box-sizing: border-box;
  }
}

@layer components {
  .button {
    padding: 0.75rem 1rem;
  }
}

@layer utilities {
  .hidden {
    display: none !important;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  line-height: 1.5;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
}

img,
picture,
video,
canvas,
svg {
  display: block;
  max-width: 100%;
}

.item {
  transition: transform 200ms ease;
}

.item:hover {
  transform: translateY(-4px);
}

/* Temporarily expose unexpected box boundaries */
.debug * {
  outline: 1px solid rgb(255 0 0 / 0.15);
}

.thumbnail {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
}

.card {
  padding: 1rem;

  & .title {
    margin: 0;
  }

  &:hover {
    transform: translateY(-2px);
  }
}

:is(h1, h2, h3) {
  line-height: 1.1;
}

:where(.card, .panel) {
  border-radius: 1rem;
}

.field:has(input:invalid) {
  border-color: #dc2626;
}

.card:has(img) {
  padding-top: 0;
}

.layout {
  display: flex;
}

@supports (display: grid) {
  .layout {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
  }
}

:root {
  --surface: #ffffff;
  --surface-muted: #f8fafc;
  --text: #0f172a;
  --text-muted: #64748b;
  --border: #e2e8f0;
  --primary: #2563eb;
  --radius: 0.875rem;
  --space: 1rem;
}

body {
  margin: 0;
  background: var(--surface-muted);
  color: var(--text);
  font-family: system-ui, sans-serif;
}

.dashboard {
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);
  min-height: 100dvh;
}

@media (max-width: 800px) {
  .dashboard {
    grid-template-columns: 1fr;
  }
}

.dashboard__content {
  min-width: 0;
  padding: clamp(1rem, 3vw, 2rem);
}

.stats {
  display: grid;
  grid-template-columns: repeat(
    auto-fit,
    minmax(min(100%, 220px), 1fr)
  );
  gap: 1rem;
}

.stat-card {
  padding: 1.25rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
}
